"""Synthetic training sets generated by running the deterministic engine.

The ML models are *surrogates* (emulators) of the scientific engine:

  * a scenario-level dataset supervises the hypothesis classifier, and
  * a per-year dataset supervises the series regressor that reproduces the
    full projection curve (not only the horizon).

Every label is produced by the engine itself, so the data is fully
reproducible (fixed seed) and needs no external source. The generators are
pure (no database, no I/O), which keeps them unit-testable and safe to run
inside the hermetic test suite.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Optional

import numpy as np

from app.models.scenario import SeaLevelRise
from app.simulations.engine import calculate_state, run_simulation

# Scenario-level features (used by the hypothesis classifier).
FEATURE_NAMES: list[str] = [
    "restoration_level",
    "sea_level_rise",
    "horizon_year",
    "baseline_area_ha",
    "baseline_carbon_density",
]

# Series features add the normalized time position along the projection.
SERIES_FEATURE_NAMES: list[str] = [*FEATURE_NAMES, "progress"]

# Multi-output targets predicted for every point of the curve.
SERIES_TARGET_NAMES: list[str] = [
    "retained_carbon",
    "effective_area_ha",
    "vegetation_cover",
    "variation_pct",
]

SLR_ENCODING: dict[SeaLevelRise, float] = {
    SeaLevelRise.LOW: 0.0,
    SeaLevelRise.MEDIUM: 1.0,
    SeaLevelRise.HIGH: 2.0,
}
_SLR_BY_CODE: dict[float, SeaLevelRise] = {code: slr for slr, code in SLR_ENCODING.items()}

DEFAULT_SEED = 42
DEFAULT_N_SAMPLES = 8000
DEFAULT_N_SCENARIOS = 2000
DEFAULT_PROGRESS_PER_SCENARIO = 16
# Fraction of scenarios sampled near the restoration boundaries (0% and 100%).
# Tree ensembles are biased at the edges of the feature range; oversampling the
# extremes keeps the surrogate accurate for the boundary scenarios.
DEFAULT_EDGE_FRAC = 0.5

# Sampling ranges for the generated scenarios.
_RESTORATION_RANGE = (0.0, 100.0)
_HORIZON_RANGE = (2030, 2100)
_AREA_RANGE = (50.0, 300.0)
_DENSITY_RANGE = (50.0, 120.0)
_EDGE_LOW_RANGE = (0.0, 12.0)
_EDGE_HIGH_RANGE = (88.0, 100.0)


@dataclass
class TrainingData:
    """Feature matrix plus the engine labels used to supervise the classifier."""

    X: np.ndarray                  # shape (n_samples, n_features)
    y_regression: np.ndarray       # shape (n_samples, 2): [variation_pct, horizon_carbon]
    y_meets: np.ndarray            # shape (n_samples,): 0/1 hypothesis label
    feature_names: list[str]

    @property
    def n_samples(self) -> int:
        return int(self.X.shape[0])


@dataclass
class SeriesTrainingData:
    """Per-year feature matrix and the four state targets."""

    X: np.ndarray                  # shape (n_rows, n_series_features)
    Y: np.ndarray                  # shape (n_rows, n_targets)
    feature_names: list[str]
    target_names: list[str]

    @property
    def n_rows(self) -> int:
        return int(self.X.shape[0])


def _decode_slr(code: float) -> SeaLevelRise:
    return _SLR_BY_CODE[float(code)]


def _sample_restoration(rng: np.random.Generator, n: int, edge_frac: float) -> np.ndarray:
    """Sample restoration levels, concentrating part of them near 0% and 100%."""
    edge_frac = max(0.0, min(1.0, edge_frac))
    n_edge = int(round(n * edge_frac))
    n_uniform = n - n_edge
    n_low = n_edge // 2
    n_high = n_edge - n_low
    values = np.concatenate(
        [
            rng.uniform(*_RESTORATION_RANGE, n_uniform),
            rng.uniform(*_EDGE_LOW_RANGE, n_low),
            rng.uniform(*_EDGE_HIGH_RANGE, n_high),
        ]
    )
    rng.shuffle(values)
    return values


def generate_dataset(
    n_samples: int = DEFAULT_N_SAMPLES,
    seed: int = DEFAULT_SEED,
    params: Optional[dict[str, float]] = None,
    edge_frac: float = DEFAULT_EDGE_FRAC,
) -> TrainingData:
    """Run the engine over a randomized grid of scenarios (scenario-level labels)."""
    if n_samples <= 0:
        raise ValueError("n_samples debe ser mayor que cero")

    rng = np.random.default_rng(seed)
    restoration = _sample_restoration(rng, n_samples, edge_frac)
    slr_codes = rng.integers(0, 3, n_samples).astype(float)
    horizon = rng.integers(_HORIZON_RANGE[0], _HORIZON_RANGE[1] + 1, n_samples)
    area = rng.uniform(*_AREA_RANGE, n_samples)
    density = rng.uniform(*_DENSITY_RANGE, n_samples)

    X = np.column_stack([restoration, slr_codes, horizon, area, density])
    y_variation = np.empty(n_samples, dtype=float)
    y_carbon = np.empty(n_samples, dtype=float)
    y_meets = np.empty(n_samples, dtype=np.int64)

    for i in range(n_samples):
        result = run_simulation(
            restoration_level=float(restoration[i]),
            sea_level_rise=_decode_slr(slr_codes[i]),
            horizon_year=int(horizon[i]),
            baseline_area_ha=float(area[i]),
            baseline_carbon_density=float(density[i]),
            params=params,
        )
        y_variation[i] = result["horizon_variation_pct"]
        y_carbon[i] = result["horizon_carbon"]
        y_meets[i] = 1 if result["meets_hypothesis"] else 0

    return TrainingData(
        X=X,
        y_regression=np.column_stack([y_variation, y_carbon]),
        y_meets=y_meets,
        feature_names=list(FEATURE_NAMES),
    )


def generate_series_dataset(
    n_scenarios: int = DEFAULT_N_SCENARIOS,
    progress_per_scenario: int = DEFAULT_PROGRESS_PER_SCENARIO,
    seed: int = DEFAULT_SEED,
    params: Optional[dict[str, float]] = None,
    edge_frac: float = DEFAULT_EDGE_FRAC,
) -> SeriesTrainingData:
    """Build a per-year dataset so the model can reproduce the whole curve.

    Each scenario contributes several normalized time positions (always
    including 0.0 and 1.0), and every row stores the four engine state values
    at that point.
    """
    if n_scenarios <= 0:
        raise ValueError("n_scenarios debe ser mayor que cero")
    if progress_per_scenario < 2:
        raise ValueError("progress_per_scenario debe ser al menos 2")

    rng = np.random.default_rng(seed)
    restoration = _sample_restoration(rng, n_scenarios, edge_frac)
    slr_codes = rng.integers(0, 3, n_scenarios).astype(float)
    horizon = rng.integers(_HORIZON_RANGE[0], _HORIZON_RANGE[1] + 1, n_scenarios)
    area = rng.uniform(*_AREA_RANGE, n_scenarios)
    density = rng.uniform(*_DENSITY_RANGE, n_scenarios)

    extra = rng.uniform(0.0, 1.0, (n_scenarios, progress_per_scenario - 2))
    progress = np.concatenate(
        [
            np.zeros((n_scenarios, 1)),
            extra,
            np.ones((n_scenarios, 1)),
        ],
        axis=1,
    )

    total = n_scenarios * progress_per_scenario
    X = np.empty((total, len(SERIES_FEATURE_NAMES)), dtype=float)
    Y = np.empty((total, len(SERIES_TARGET_NAMES)), dtype=float)

    row = 0
    for i in range(n_scenarios):
        slr = _decode_slr(slr_codes[i])
        for j in range(progress_per_scenario):
            p = float(progress[i, j])
            state = calculate_state(
                restoration_level=float(restoration[i]),
                sea_level_rise=slr,
                progress=p,
                baseline_area_ha=float(area[i]),
                baseline_carbon_density=float(density[i]),
                params=params,
            )
            X[row] = [
                restoration[i],
                slr_codes[i],
                horizon[i],
                area[i],
                density[i],
                p,
            ]
            Y[row] = [
                state["retained_carbon"],
                state["effective_area_ha"],
                state["vegetation_cover"],
                state["variation_pct"],
            ]
            row += 1

    return SeriesTrainingData(
        X=X,
        Y=Y,
        feature_names=list(SERIES_FEATURE_NAMES),
        target_names=list(SERIES_TARGET_NAMES),
    )
